# Source for www/js/lectures.js — hand-written lecture content for every Learn unit.
# Each unit: hook, 3 ideas (title, body), worked example (q, steps, ans), check (q, choices, correct index, why).
import json

def U(hook, ideas, ex, check):
    q, steps, ans = ex
    cq, choices, a, why = check
    return {"hook": hook, "ideas": [{"t": t, "b": b} for t, b in ideas], "example": {"q": q, "steps": steps, "ans": ans},
            "check": {"q": cq, "choices": choices, "a": a, "why": why}}

