L["counting_and_probability"] = [
  U(r"Counting is careful multiplying, and probability is counting with a fraction at the end.",
    [("Multiplication principle", r"Independent choices multiply: a 3-letter code from $26$ letters has $26^3=17576$ possibilities."),
     ("Probability", r"With equally likely outcomes, probability $=\frac{\text{favourable}}{\text{total}}$. Rolling a $5$ or $6$: $\frac26=\frac13$."),
     ("Complements", r"Sometimes it's easier to count what you don't want: $P(\text{at least one head in 3 flips})=1-\frac18=\frac78$.")],
    (r"Two dice are rolled. What is the probability the sum is $7$?", [r"There are $6\times6=36$ equally likely outcomes.", r"Sum $7$: $(1,6),(2,5),(3,4),(4,3),(5,2),(6,1)$, which is $6$ outcomes.", r"$\frac6{36}=\frac16$."], r"$\frac16$"),
    (r"How many 4-digit PINs have no repeated digits?", [r"$5040$", r"$10000$", r"$3024$", r"$6561$"], 0, r"$10\cdot9\cdot8\cdot7=5040$.")),
  U(r"Does order matter? That one question decides between permutations and combinations.",
    [("Permutations", r"$n$ things in a row can be ordered in $n!$ ways. Choosing and ordering $k$ of $n$ gives $\frac{n!}{(n-k)!}$."),
     ("Combinations", r"Choosing $k$ of $n$ when order doesn't matter: $\binom nk=\frac{n!}{k!(n-k)!}$. So $\binom52=10$."),
     ("Repeated letters", r"Divide out the repeats: MISSISSIPPI has $\frac{11!}{4!\,4!\,2!}=34650$ arrangements.")],
    (r"A committee of $3$ is chosen from $5$ boys and $4$ girls. How many committees have exactly $2$ girls?", [r"Choose the girls: $\binom42=6$.", r"Choose the boy: $\binom51=5$.", r"Multiply: $6\cdot5=30$."], r"$30$"),
    (r"How many ways can the letters of BOOK be arranged?", [r"$12$", r"$24$", r"$6$", r"$4$"], 0, r"$\frac{4!}{2!}=12$, because the two O's are identical.")),
  U(r"Three tools for cases that look messy: stars and bars, inclusion–exclusion and expected value.",
    [("Stars and bars", r"Sharing $n$ identical items among $k$ people (some may get none) can be done in $\binom{n+k-1}{k-1}$ ways."),
     ("Inclusion–exclusion", r"$|A\cup B|=|A|+|B|-|A\cap B|$. The numbers from $1$ to $100$ divisible by $2$ or $3$: $50+33-16=67$."),
     ("Expected value is linear", r"The expected total of two dice is $3.5+3.5=7$, with no need to list all the outcomes.")],
    (r"How many ways can $6$ identical sweets be shared among $3$ children?", [r"Stars and bars: $6$ stars and $2$ bars.", r"Arrange the $8$ symbols by choosing where the bars go: $\binom82$.", r"$\binom82=28$."], r"$28$"),
    (r"How many integers from $1$ to $60$ are divisible by $4$ or $6$?", [r"$20$", r"$25$", r"$15$", r"$24$"], 0, r"$15+10-5=20$. The overlap is multiples of $\operatorname{lcm}(4,6)=12$, and there are $5$ of them.")),
  U(r"Pascal's triangle links counting to algebra.",
    [("Pascal's rule", r"$\binom nk=\binom{n-1}{k-1}+\binom{n-1}{k}$: each entry of Pascal's triangle is the sum of the two above it."),
     ("Binomial theorem", r"$(x+y)^n=\sum_k\binom nk x^ky^{n-k}$. The coefficient of $x^2$ in $(x+1)^5$ is $\binom52=10$."),
     ("Geometric probability", r"When outcomes are points in a region, probability $=$ favourable length or area $\div$ total length or area.")],
    (r"Find the coefficient of $x^3$ in $(2x+1)^5$.", [r"The $x^3$ term is $\binom53(2x)^3\cdot1^2$.", r"$\binom53=10$ and $(2x)^3=8x^3$.", r"The coefficient is $10\cdot8=80$."], r"$80$"),
    (r"What is $\binom60+\binom61+\dots+\binom66$?", [r"$64$", r"$32$", r"$36$", r"$128$"], 0, r"Row $n$ of Pascal's triangle sums to $2^n$, so the answer is $2^6=64$.")),
  U(r"Harder counting comes down to splitting into cases, building up from smaller ones, and spotting symmetry.",
    [("Casework", r"Split into cases that don't overlap and add them up. Check that every outcome is counted exactly once."),
     ("Recursion", r"Build answers from smaller ones. The number of ways to climb $n$ stairs taking $1$ or $2$ at a time satisfies $a_n=a_{n-1}+a_{n-2}$."),
     ("Symmetry", r"Outcomes that are equally likely by symmetry have equal probabilities, which often halves the work.")],
    (r"How many ways can you climb $6$ stairs taking $1$ or $2$ steps at a time?", [r"$a_1=1$, $a_2=2$, and $a_n=a_{n-1}+a_{n-2}$.", r"$a_3=3$, $a_4=5$, $a_5=8$.", r"$a_6=13$."], r"$13$"),
    (r"A fair coin is flipped $4$ times. What is the probability of more heads than tails?", [r"$\frac5{16}$", r"$\frac12$", r"$\frac38$", r"$\frac3{16}$"], 0, r"Three heads happens $4$ ways and four heads $1$ way: $5$ out of $16$. By symmetry, more tails is also $\frac5{16}$ and a tie is $\frac6{16}$.")),
]
