# Mixed olympiad: one idea from each topic, with alternating examples.
topics = ["oly_nt", "oly_comb", "oly_alg", "oly_geo"]
L["oly_mixed"] = []
for u in range(5):
    src = L[topics[u % 4]][u]
    ideas = [L[t][u]["ideas"][0] for t in topics[:3]]
    L["oly_mixed"].append({"hook": "A mix of olympiad ideas: one from number theory, combinatorics and algebra, with a worked example.", "ideas": ideas, "example": src["example"], "check": L[topics[(u + 1) % 4]][u]["check"]})

for k, units in L.items():
    assert len(units) == 5, k
    for u in units:
        assert len(u["ideas"]) == 3 and 0 <= u["check"]["a"] < len(u["check"]["choices"]), k
out = "// Hand-written lecture content for every Learn unit (generated from lectures_src.py).\nexport const LECTURES = " + json.dumps(L, ensure_ascii=False, indent=0) + ";\n"
open(__import__("os").path.join(__import__("os").path.dirname(__file__), "..", "www", "js", "lectures.js"), "w").write(out)
print("ok", sum(len(v) for v in L.values()), "units")
